// m20n — first-person weapon art so every weapon reads as its description.
// Trident, halberd, void halberd, spade, maul, forge hammer, net-trident and censer flail
// get unique held sprites. Hands / gauntlet pixels are never edited; new art is a separate
// layer that fits the existing grip (handle pixels below the lock line are copied from the
// source view). Flame-sword look and all weapon FX still always draw. No balance changes.
// Kill: ?wpnart=0  or master ?m20n=0  (also honours ?m20=0).
(function () {
  const off = /[?&](wpnart=0|m20n=0|m20=0)(?:&|$)/.test(location.search);
  const M20N = window.M20N = { on: !off, ready: false, errs: [] };
  M20N.st = function () { return { on: M20N.on, ready: M20N.ready, wpnart: M20N.on, errs: M20N.errs.slice(0, 5) }; };
  if (off) return;

  const PAYLOAD = {"trident":{"spr":"","glow":"","sheen":"","w":88,"h":244},"halberd":{"spr":"","glow":"","sheen":"","w":88,"h":244},"voidhal":{"spr":"","glow":"","sheen":"","w":88,"h":244},"spade":{"spr":"","glow":"","sheen":"","w":88,"h":244},"maul":{"spr":"","glow":"","sheen":"","w":88,"h":244},"hammer":{"spr":"","glow":"","sheen":"","w":88,"h":244},"net":{"spr":"","glow":"","sheen":"","w":110,"h":150},"censer":{"spr":"","glow":"","sheen":"","w":110,"h":150}};

  function canvFromB64(b64, cb) {
    const im = new Image();
    im.onload = function () {
      const c = document.createElement('canvas'); c.width = im.width; c.height = im.height;
      const x = c.getContext('2d'); x.drawImage(im, 0, 0);
      const d = x.getImageData(0, 0, c.width, c.height);
      cb({ img: c, tex: { w: c.width, h: c.height, d: new Uint32Array(d.data.buffer) } });
    };
    im.onerror = function () { M20N.errs.push('artload'); cb(null); };
    im.src = 'data:image/png;base64,' + b64;
  }

  const KEYS = ['trident', 'halberd', 'voidhal', 'spade', 'maul', 'hammer', 'net', 'censer'];
  const ART = M20N.art = {};
  let left = KEYS.length * 3;
  function one() {
    if (--left) return;
    M20N.ready = true;
    hook();
  }
  KEYS.forEach(function (k) {
    ART[k] = {};
    ['spr', 'glow', 'sheen'].forEach(function (slot) {
      canvFromB64(PAYLOAD[k][slot], function (r) {
        if (r) {
          const name = 'vm_m20_' + k + (slot === 'spr' ? '' : '_' + slot);
          if (typeof Engine !== 'undefined') { Engine.imgs[name] = r.img; Engine.tex[name] = r.tex; }
          ART[k][slot] = r;
          ART[k][slot + 'Name'] = name;
        }
        one();
      });
    });
  });

  function current() {
    if (!M20N.on || !M20N.ready || typeof P === 'undefined' || !P || !P.mods || !P.wpn) return null;
    const m = P.mods, w = P.wpn;
    if (m.m20trident && w.sword === 'rapier') return { k: 'trident', kind: 'sword', src: ['vm_sword_rapier', 'vm_sword_rapier_glow', 'vm_sword_rapier_sheen'] };
    // void halberd also uses the storm view; check it before Stormspire
    if (m.voidhal && w.sword === 'storm') return { k: 'voidhal', kind: 'sword', src: ['vm_sword_storm', 'vm_sword_storm_glow', 'vm_sword_storm_sheen'] };
    if (m.m20halberd && w.sword === 'storm') return { k: 'halberd', kind: 'sword', src: ['vm_sword_storm', 'vm_sword_storm_glow', 'vm_sword_storm_sheen'] };
    if (m.m20spade && w.sword === 'axe') return { k: 'spade', kind: 'sword', src: ['vm_sword_axe', 'vm_sword_axe_glow', 'vm_sword_axe_sheen'] };
    if (m.m20maul && w.sword === 'great') return { k: 'maul', kind: 'sword', src: ['vm_sword_great', 'vm_sword_great_glow', 'vm_sword_great_sheen'] };
    if (m.m20forge && w.sword === 'fire') return { k: 'hammer', kind: 'sword', src: ['vm_sword_fire', 'vm_sword_fire_glow', 'vm_sword_fire_sheen'] };
    if (m.m20net && w.whip === 'chain') return { k: 'net', kind: 'whip', src: ['vm_lwhandle_chain'] };
    if (m.m20censer && w.whip === 'fire') return { k: 'censer', kind: 'whip', src: ['vm_lwhandle_fire'] };
    return null;
  }
  M20N.current = current;

  function swapIn(c) {
    const a = ART[c.k], keep = [];
    function put(name, slot) {
      if (!name || !a[slot]) return;
      keep.push([name, Engine.imgs[name], Engine.tex[name]]);
      Engine.imgs[name] = a[slot].img;
      Engine.tex[name] = a[slot].tex;
    }
    if (c.kind === 'sword') { put(c.src[0], 'spr'); put(c.src[1], 'glow'); put(c.src[2], 'sheen'); }
    else put(c.src[0], 'spr');
    return keep;
  }
  function swapOut(keep) {
    for (let i = 0; i < keep.length; i++) {
      const k = keep[i];
      Engine.imgs[k[0]] = k[1];
      Engine.tex[k[0]] = k[2];
    }
  }

  function drawCenserTip(ctx, p) {
    const x = Math.round(p[0]), y = Math.round(p[1]);
    ctx.save();
    // gold body
    ctx.fillStyle = '#3a2008'; ctx.fillRect(x - 6, y - 5, 13, 12);
    ctx.fillStyle = '#c89628'; ctx.fillRect(x - 5, y - 4, 11, 10);
    ctx.fillStyle = '#ffe08a'; ctx.fillRect(x - 4, y - 3, 4, 3);
    // green fire
    ctx.fillStyle = '#20c050'; ctx.fillRect(x - 2, y - 1, 5, 5);
    ctx.fillStyle = '#b0ff90'; ctx.fillRect(x - 1, y, 2, 2);
    // cross
    ctx.fillStyle = '#ffe8a0'; ctx.fillRect(x - 1, y - 10, 3, 6); ctx.fillRect(x - 4, y - 8, 9, 2);
    ctx.restore();
  }
  function drawNetBag(ctx, pts) {
    if (!pts || pts.length < 4) return;
    const n = pts.length, i0 = (n * 0.55) | 0;
    ctx.save();
    for (let i = i0; i < n; i++) {
      const s = (i - i0) / Math.max(1, n - 1 - i0);
      const w = 2 + 12 * s * s;
      const p = pts[i], q = pts[Math.max(i0, i - 1)];
      const dx = p[0] - q[0], dy = p[1] - q[1], L = Math.hypot(dx, dy) || 1;
      const nx = -dy / L, ny = dx / L;
      const a0x = p[0] + nx * w, a0y = p[1] + ny * w, a1x = p[0] - nx * w, a1y = p[1] - ny * w;
      ctx.fillStyle = (i % 2) ? '#d0b878' : '#6a4e20';
      ctx.fillRect(a0x | 0, a0y | 0, 2, 2);
      ctx.fillRect(a1x | 0, a1y | 0, 2, 2);
      if (i % 2 === 0) {
        ctx.strokeStyle = 'rgba(200,176,96,0.7)'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(a0x, a0y); ctx.lineTo(a1x, a1y); ctx.stroke();
      }
    }
    const tip = pts[n - 1];
    ctx.fillStyle = '#686878';
    ctx.fillRect((tip[0] | 0) - 2, (tip[1] | 0), 2, 3);
    ctx.fillRect((tip[0] | 0) + 2, (tip[1] | 0), 2, 3);
    ctx.fillRect((tip[0] | 0) - 1, (tip[1] | 0) + 2, 3, 2);
    ctx.restore();
  }
  function overlayPts(ctx, pts, wt) {
    const c = current();
    if (!c || !pts || !pts.length) return;
    try {
      if (c.k === 'net') drawNetBag(ctx, pts);
      if (c.k === 'censer') drawCenserTip(ctx, pts[pts.length - 1]);
    } catch (e) { M20N.errs.push('tip'); }
  }

  function hook() {
    if (typeof drawViewModel !== 'function') { M20N.errs.push('no-dvm'); return; }
    const _dvm = drawViewModel;
    drawViewModel = function (ctx, cam) {
      const c = current();
      if (!c) return _dvm.apply(this, arguments);
      const keep = swapIn(c);
      try { return _dvm.apply(this, arguments); }
      finally { swapOut(keep); }
    };
    if (typeof bloodyBlade === 'function') {
      const _bb = bloodyBlade;
      bloodyBlade = function (name) {
        const c = current();
        if (c && c.kind === 'sword' && name === c.src[0] && ART[c.k] && ART[c.k].sprName) name = ART[c.k].sprName;
        return _bb(name);
      };
    }
    function wrapPts(fnName) {
      if (typeof window[fnName] !== 'function') return;
      const _f = window[fnName];
      window[fnName] = function () {
        const r = _f.apply(this, arguments);
        try {
          // drawLash / drawWhipTo don't return pts; hook WFX instead. For drawCoil the last arg is unused.
        } catch (e) {}
        return r;
      };
    }
    if (window.WFX) {
      if (typeof WFX.lash === 'function') {
        const _l = WFX.lash;
        WFX.lash = function (ctx, pts, wt) { const r = _l.apply(this, arguments); overlayPts(ctx, pts, wt); return r; };
      }
      if (typeof WFX.coil === 'function') {
        const _c = WFX.coil;
        WFX.coil = function (ctx, pts, c, t) { const r = _c.apply(this, arguments); overlayPts(ctx, pts, 0); return r; };
      }
    }
    // also wrap drawLash / drawWhipTo / drawCoil in case WFX is missing or quality is off
    const _dl = typeof drawLash === 'function' ? drawLash : null;
    if (_dl) {
      // patch by intercepting after via a local capture: re-run overlay using a dummy sampled from arguments is hard.
      // Instead lightly wrap the internal pts by shimming ctx during the call? Too heavy.
      // Fallback: after drawLash, if current is net/censer, the coil/lash already went through WFX when GFX is on.
      // Always-on overlay: wrap drawLash and reconstruct a short tip from hx/hy is wrong.
      // Monkey-patch: wrap chainCord and fireCord? chainCord is used for net (chain view). fireCord for censer.
    }
    if (typeof chainCord === 'function') {
      const _cc = chainCord;
      chainCord = function (ctx, pts, amt) {
        const r = _cc.apply(this, arguments);
        if (current() && current().k === 'net') overlayPts(ctx, pts, amt);
        return r;
      };
    }
    if (typeof fireCord === 'function') {
      const _fc = fireCord;
      fireCord = function (ctx, pts, amt) {
        const r = _fc.apply(this, arguments);
        if (current() && current().k === 'censer') overlayPts(ctx, pts, amt);
        return r;
      };
    }
    if (typeof drawCoil === 'function') {
      const _dc = drawCoil;
      drawCoil = function (ctx, top, hx, hy, c, t, reeling) {
        const r = _dc.apply(this, arguments);
        try {
          const cur = current();
          if (!cur) return r;
          // hanging tip roughly at the coil centre
          const C = [hx + 54 + 6 * (1 - c), hy + 4 + 4 * (0.35 + 0.65 * c)];
          if (cur.k === 'censer') drawCenserTip(ctx, [C[0], C[1] + 18 * c]);
          if (cur.k === 'net') overlayPts(ctx, [top, [C[0], C[1] + 8], [C[0] + 6, C[1] + 16 * c]], 0);
        } catch (e) { M20N.errs.push('coil'); }
        return r;
      };
    }
  }
})();
